-- TAV com a tabela de itens para a contagem ({{tabela_itens}}) e assinatura de quem imprime (responsável pelo pré-recebimento).
-- Atualiza o modelo padrão e o modelo em uso, se ainda for o padrão (nunca trocado por um administrador).
update modelos set arquivo = decode('', 'base64'), nome_arquivo = 'tav.odt', atualizado_em = now()
 where chave = 'tav_padrao' or (chave = 'tav' and atualizado_por is null);
